import {useEffect,useState} from 'react';
import type {QueueType,QueueTypeConfiguration} from '../../../shared/queueTypes';
const labels:Record<QueueType,{name:string;description:string}>={simple:{name:'Simple queue',description:'Call customers in order. You can include a service without reserving resources.'},resource:{name:'Resource-based queue',description:'Manage requests that share limited people, rooms or equipment.'},workflow:{name:'Queue workflow',description:'Guide one customer journey through sequential service stations.'}};
export function QueueTypeSettings({configuration,canEdit,busy,onSave}:{configuration:QueueTypeConfiguration|null;canEdit:boolean;busy:boolean;onSave:(type:QueueType)=>Promise<void>}){
 const [selected,setSelected]=useState<QueueType>('simple');const [confirmed,setConfirmed]=useState(false);const [error,setError]=useState('');
 useEffect(()=>{setSelected(configuration?.type||'simple');setConfirmed(false);setError('');},[configuration?.scope.tenantSlug,configuration?.scope.locationSlug,configuration?.revision]);
 if(!configuration)return <p role="status">Loading this location’s queue type…</p>;
 return <section aria-labelledby="queue-type-heading" className="space-y-4"><h2 id="queue-type-heading">Queue type</h2><p>{configuration.notice}</p><fieldset disabled={!canEdit||busy} className="space-y-3"><legend>How should new requests move through this location?</legend>{(Object.keys(labels) as QueueType[]).map(type=>{const allowed=configuration.capabilities[type];const ready=configuration.readiness[type];return <label key={type} className="flex min-h-12 items-start gap-3 rounded-md border p-4"><input type="radio" name="queue-type" value={type} checked={selected===type} disabled={!allowed||!ready.ready} onChange={()=>{setSelected(type);setConfirmed(false);setError('');}}/><span><strong>{labels[type].name}</strong><span className="block">{labels[type].description}</span>{!allowed?<span className="block">Not included in your current plan.</span>:!ready.ready?<span className="block">{ready.reason}</span>:null}</span></label>;})}</fieldset><label className="flex min-h-12 items-center gap-3"><input type="checkbox" checked={confirmed} disabled={!canEdit||busy||selected===configuration.type} onChange={event=>setConfirmed(event.target.checked)}/>Apply this change to future requests only.</label>{error?<p role="alert">{error}</p>:null}<button type="button" disabled={!canEdit||busy||!confirmed||selected===configuration.type} onClick={()=>{setError('');void onSave(selected).catch(reason=>setError(reason instanceof Error?reason.message:'The queue type could not be saved.'));}}>{busy?'Saving…':'Save queue type'}</button></section>;
}
